#include <iostream>
#include <vector>
using namespace std;

int main() {
	int n, m;
	cin >> n >> m;
	vector<int> a(m);
	for (int i = 0; i < m; i++) cin >> a[i];
	vector<int> cnt(n + 1); // 各候補者の得票数
	int ans = 0; // 現時点での当選者
	for (int i = 0; i < m; i++) {
		cnt[a[i]]++;
		if (cnt[ans] < cnt[a[i]]) ans = a[i];
		else if (cnt[ans] == cnt[a[i]]) ans = min(ans, a[i]);
		cout << ans << '\n';
	}
}
